css:
.phero .sub a{color:#7FD1A8}.paper p a:not(.btn),.paper li a{color:var(--green)}
.os-three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:8px}.os-three>div,.os-two>div{background:#fff;border:1px solid var(--border);border-radius:14px;padding:18px 20px}
.os-three h3,.os-two h3{margin:0 0 6px;font-size:18px}.os-three p,.os-two p{font-size:15px;line-height:1.6;color:var(--muted)}
.os-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:8px}.os-two .in{background:#EBF5F0;border-color:#CFE6DA}.os-two .out{background:#F7F2E9;border-color:#E9DFCB}
.os-sub{margin:28px 0 8px;font-size:20px}.os-p{font-size:15.5px;line-height:1.7;color:var(--muted);max-width:52em;margin-top:10px!important}
.os-list{padding-left:20px;font-size:15.5px;line-height:1.75;color:var(--muted);max-width:52em}.os-list b{color:var(--text)}
.os-phases{padding-left:22px;display:flex;flex-direction:column;gap:10px;font-size:15.5px;line-height:1.6;color:var(--muted);max-width:56em}.os-phases b{color:var(--text)}
.os-st{display:inline-block;margin-left:6px;font:600 11px/1.6 var(--mono);text-transform:uppercase;letter-spacing:.06em;background:#EFEDE7;color:#4A4845;border-radius:999px;padding:0 8px}
@media (max-width:900px){.os-three,.os-two{grid-template-columns:minmax(0,1fr)}}
